def pre(xs):
    # Contract covers lists of 0..6 ints in [-5, 5]; the verifier enumerates
    # exactly these, but we check explicitly for clarity.
    if len(xs) > 6:
        return False
    for x in xs:
        if x < -5 or x > 5:
            return False
    return True


def _expected(xs):
    # Distinct values of xs, each once, in order of first occurrence.
    exp = []
    for x in xs:
        seen = False
        for y in exp:
            if y == x:
                seen = True
        if not seen:
            exp.append(x)
    return exp


def post(xs, result):
    exp = _expected(xs)
    if len(result) != len(exp):
        return False
    for i in range(len(exp)):
        if result[i] != exp[i]:
            return False
    return True
